            }

            pos += try writeLine(buffer[pos..], final_line);
        }

        // Blank line between verses (except after last verse)
        if (verse != end_verse) {
            if (pos < buffer.len) {
                buffer[pos] = '\n';
                pos += 1;
            }
        }
    }

    return buffer[0..pos];
}

fn writeLine(buf: []u8, parts: anytype) !usize {
    var pos: usize = 0;
    inline for (@typeInfo(@TypeOf(parts)).Tuple.fields) |field, i| {
        const part = @field(parts, i);
        const len = part.len;
        if (pos + len > buf.len) return error.BufferTooSmall;
        std.mem.copy(u8, buf[pos..pos+len], part);
        pos += len;
    }
    if (pos < buf.len) {
        buf[pos] = '\n';
        pos += 1;
    } else {
        return error.BufferTooSmall;
    }
    return pos;
}
