    const animals = [_][]const u8{ "fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse" };
    const comments = [_][]const u8{
        "",
        "It wriggled and jiggled and tickled inside her.",
        "How absurd to swallow a bird!",
        "Imagine that, to swallow a cat!",
        "What a hog, to swallow a dog!",
        "Just opened her throat and swallowed a goat!",
        "I don't know how she swallowed a cow!",
        "She's dead, of course!",
    };
    const final_line = "I don't know why she swallowed the fly. Perhaps she'll die.";

    for (start_verse..=end_verse) |verse| {
        // First line
        const animal = animals[@intCast(verse - 1)];
        pos += try writeLine(buffer[pos..], "I know an old lady who swallowed a ", animal, ".");

